@echo off
title FITNESS LEGENDS - Servidor Central de Sincronizacion LAN
color 0D

echo ======================================================================
echo           FITNESS LEGENDS GYM - VINCULACION EN TIEMPO REAL
echo           Servidor Central de Socios, Huellas y Torniquete
echo ======================================================================
echo.
echo [*] Obteniendo la Direccion IP de esta computadora en tu Red Local...
for /f "tokens=4" %%a in ('route print ^| findstr 0.0.0.0 ^| findstr /v "0.0.0.0.*0.0.0.0"') do (
    set LOCAL_IP=%%a
)
echo.
echo ======================================================================
echo   DIRECCIONES PARA VINCULAR AMBAS COMPUTADORAS EN TU GYM:
echo ======================================================================
echo.
echo  [1] COMPUTADORA DEL ADMINISTRADOR (Este equipo):
echo      Abre: http://localhost:5174
echo.
echo  [2] COMPUTADORA DEL TORNIQUETE (Equipo en entrada/torniquete):
echo      En el navegador de la otra computadora, abre:
echo      http://%LOCAL_IP%:5174/?mode=terminal
echo.
echo  [3] ESTADO DE LA VINCULACION:
echo      Puerto 3001: Base de Datos de Socios y Huellas (Activo)
echo      Puerto 5174: Interfaz Web y Terminal (Activo)
echo      Cualquier socio registrado en el Administrador se refleja
echo      de inmediato en el Torniquete, y cualquier entrada se registra
echo      en vivo en el Administrador.
echo ======================================================================
echo.
echo [*] Iniciando Servidor de Sincronizacion...
start "FITNESS LEGENDS - Sync Server" /MIN node "%~dp0..\LEGENDS\server\syncServer.cjs"
echo [*] Iniciando Servidor Web con soporte de Red Local...
cd /d "%~dp0..\LEGENDS"
call npm.cmd run dev -- --host --port 5174
pause

$targetDir = "c:\Users\andre\OneDrive\Desktop\gym\accesos directos"
$iconPath = "c:\Users\andre\OneDrive\Desktop\gym\LEGENDS\build\icon.ico"
$wsh = New-Object -ComObject WScript.Shell

$shortcuts = @(
    @{
        Name = "1. Sistema ERP Administrador.lnk"
        Target = "$targetDir\1. INICIAR_SISTEMA_ADMINISTRADOR_ERP.bat"
        Description = "Fitness Legends - Sistema ERP Central para Administrador"
    },
    @{
        Name = "2. Terminal Torniquete Acceso.lnk"
        Target = "$targetDir\2. INICIAR_TERMINAL_TORNIQUETE.bat"
        Description = "Fitness Legends - Terminal de Control de Acceso para Torniquete"
    },
    @{
        Name = "3. Cartera de Clientes.lnk"
        Target = "$targetDir\3. ACCESO_CARTERA_DE_CLIENTES.bat"
        Description = "Fitness Legends - Cartera de Clientes y Membresias"
    },
    @{
        Name = "4. Vincular Equipos en Red LAN.lnk"
        Target = "$targetDir\4. SERVIDOR_SINCRONIZACION_LAN_(VINCULAR_EQUIPOS).bat"
        Description = "Fitness Legends - Servidor de Sincronizacion para conectar Torniquete y Admin"
    }
)

foreach ($sc in $shortcuts) {
    $lnkPath = Join-Path $targetDir $sc.Name
    $shortcut = $wsh.CreateShortcut($lnkPath)
    $shortcut.TargetPath = $sc.Target
    $shortcut.WorkingDirectory = $targetDir
    $shortcut.Description = $sc.Description
    if (Test-Path $iconPath) {
        $shortcut.IconLocation = $iconPath
    }
    $shortcut.Save()
    Write-Host "Created shortcut: $($sc.Name)"
}

