// Cargar socios reales desde el Servidor Central de Sincronización si está activo
async function loadRealMembersFromSyncServer() {
  try {
    const res = await fetch('http://localhost:3001/api/sync/members', { signal: AbortSignal.timeout(2000) });
    if (res.ok) {
      const data = await res.json();
      if (Array.isArray(data.members) && data.members.length > 0) {
        members = data.members.map(m => {
          const daysRem = typeof m.daysRemaining === 'number' ? m.daysRemaining : 30;
          let calcStatus = 'active';
          if (daysRem <= 0) calcStatus = 'expired';
          else if (daysRem <= 5) calcStatus = 'expiring_soon';
          return {
            id: m.id || 'MEM-' + Math.random().toString(36).substring(2, 6).toUpperCase(),
            fullName: m.fullName || m.name || 'Socio Sin Nombre',
            documentId: m.documentId || m.dni || 'S/N',
            email: m.email || '',
            phone: m.phone || '',
            avatarUrl: m.avatarUrl || 'https://images.unsplash.com/photo-1534528741775-53994a69daeb?auto=format&fit=crop&w=150&q=80',
            planType: m.planType || 'monthly',
            planName: m.planName || 'Membresía Activa',
            price: Number(m.price || 850),
            status: m.status || calcStatus,
            daysRemaining: daysRem,
            startDate: m.startDate || '2026-01-01',
            endDate: m.endDate || '2026-12-31',
            biometricRegistered: Boolean(m.biometricRegistered || m.hasBiometric || (m.fingerprints && m.fingerprints.length > 0)),
            checkInsCount: m.checkInsCount || 0,
            totalSpent: Number(m.totalSpent || 0),
            emergency: m.emergency || '',
            medicalNotes: m.medicalNotes || ''
          };
        });
        updateKPIs();
        render();
      }
    }
  } catch (err) {
    console.log('[SYNC] Modo independiente o servidor en espera:', err);
  }
}

// Initialize on page load
updateKPIs();
render();
loadRealMembersFromSyncServer();

