@echo off
title FITNESS LEGENDS GYM - Acceso Web al ERP
color 0A

echo ======================================================================
echo           FITNESS LEGENDS GYM - ACCESO WEB AL ERP
echo ======================================================================
echo.

set "ELECTRON_EXE=%~dp0..\LEGENDS\node_modules\electron\dist\electron.exe"
set "WEB_SERVER=%~dp0..\LEGENDS\server\webServer.cjs"

netstat -ano | findstr ":3001" >nul
if %errorlevel% neq 0 (
    echo [*] Iniciando Servidor Central de Sincronizacion...
    if exist "%ELECTRON_EXE%" (
        set "ELECTRON_RUN_AS_NODE=1"
        start "FITNESS LEGENDS - Web Server" /MIN "%ELECTRON_EXE%" "%WEB_SERVER%"
        timeout /t 2 >nul
    )
)

echo [*] Abriendo Sistema ERP en tu navegador web predeterminado...
start http://localhost:5173
start http://localhost:5174

timeout /t 2 >nul
exit

@echo off
title FITNESS LEGENDS GYM - Punto de Venta (POS)
color 0E

echo ======================================================================
echo           FITNESS LEGENDS GYM - PUNTO DE VENTA (POS)
echo           Cobro de Membresias, Suplementos, Bebidas y Pases
echo ======================================================================
echo.

set "APP_DIR=%~dp0..\LEGENDS\release\FITNESS_LEGENDS_TERMINAL-win32-x64"
set "EXE_FILE=%APP_DIR%\FitnessLegends.exe"

echo [*] Abriendo Punto de Venta...
start http://localhost:5173/?tab=pos
start http://localhost:5174/?tab=pos

if exist "%EXE_FILE%" (
    start "" "%EXE_FILE%" --main
)

timeout /t 2 >nul
exit

@echo off
title FITNESS LEGENDS GYM - Servidor Central de Sincronizacion
color 0F

echo ======================================================================
echo     FITNESS LEGENDS GYM - SERVIDOR DE SINCRONIZACION (PUERTO 3001)
echo ======================================================================
echo.

set "ELECTRON_EXE=%~dp0..\LEGENDS\node_modules\electron\dist\electron.exe"
set "SERVER_SCRIPT=%~dp0..\LEGENDS\server\syncServer.cjs"

if exist "%ELECTRON_EXE%" (
    set "ELECTRON_RUN_AS_NODE=1"
    echo [*] Iniciando servidor con motor central...
    "%ELECTRON_EXE%" "%SERVER_SCRIPT%"
) else (
    echo [*] Iniciando con node del sistema...
    node "%SERVER_SCRIPT%"
)

pause

@echo off
title FITNESS LEGENDS - Vinculacion LAN con Torniquete
color 0B

echo ======================================================================
echo     FITNESS LEGENDS GYM - ASISTENTE DE VINCULACION EN RED LAN
echo ======================================================================
echo.

for /f "tokens=4" %%a in ('route print ^| findstr 0.0.0.0.*0.0.0.0 ^| findstr /v "Default"') do (
    set "MY_IP=%%a"
)

echo  [+] Direccion IP de esta computadora de Administracion: %MY_IP%
echo.
echo ----------------------------------------------------------------------
echo  PARA CONFIGURAR LA COMPUTADORA DEL TORNIQUETE:
echo ----------------------------------------------------------------------
echo.
echo  1. En la PC del Torniquete, abre el navegador web e ingresa:
echo     http://%MY_IP%:5174/?mode=terminal
echo.
echo  2. O en la aplicacion de Torniquete, configura el Servidor Central en:
echo     http://%MY_IP%:3001
echo.
echo ======================================================================
echo [*] Comprobando puerto 3001...
netstat -ano | findstr ":3001" >nul
if %errorlevel% equ 0 (
    echo [OK] El Servidor de Sincronizacion esta ACTIVO y listo para recibir al Torniquete.
) else (
    echo [!] Servidor inactivo. Iniciando ahora...
    start "FITNESS LEGENDS - Sync Server" /MIN "%~dp06. SERVIDOR_DE_SINCRONIZACION.bat"
)
echo ======================================================================
echo.
pause
